import React from 'react';
import styled from 'styled-components';
import { LogIn } from 'lucide-react';
import { Card, Button } from '../styles/GlobalStyles';

const LoginContainer = styled.div`
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  background: url('/background.jpg') center/cover;
  position: relative;
  
  &::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: linear-gradient(135deg, rgba(30, 60, 114, 0.9) 0%, rgba(42, 82, 152, 0.8) 50%, rgba(22, 160, 133, 0.9) 100%);
  }
`;

const LoginCard = styled(Card)`
  position: relative;
  z-index: 1;
  text-align: center;
  max-width: 400px;
  width: 100%;
`;

const Logo = styled.div`
  margin-bottom: 2rem;
  
  img {
    width: 80px;
    height: 80px;
    border-radius: 16px;
    margin-bottom: 1rem;
  }
  
  h1 {
    color: #333;
    font-size: 2rem;
    font-weight: 700;
    margin-bottom: 0.5rem;
  }
  
  p {
    color: #666;
    font-size: 1rem;
  }
`;

const GoogleButton = styled(Button)`
  width: 100%;
  padding: 16px;
  font-size: 16px;
  background: linear-gradient(135deg, #27ae60 0%, #16a085 100%);
  
  &:hover {
    transform: translateY(-2px);
    box-shadow: 0 10px 20px rgba(39, 174, 96, 0.3);
  }
`;

interface LoginPageProps {
  onSignIn: () => void;
  loading: boolean;
}

export const LoginPage: React.FC<LoginPageProps> = ({ onSignIn, loading }) => {
  return (
    <LoginContainer>
      <LoginCard>
        <Logo>
          <img src="/LOGO_TOPO.jpg" alt="Logo" />
          <h1>Economia Doméstica</h1>
          <p>Gerencie suas finanças de forma inteligente</p>
        </Logo>
        
        <GoogleButton onClick={onSignIn} disabled={loading}>
          <LogIn size={20} />
          {loading ? 'Entrando...' : 'Entrar com Google'}
        </GoogleButton>
      </LoginCard>
    </LoginContainer>
  );
};