import React, { useState } from 'react';
import styled from 'styled-components';
import { Plus, X } from 'lucide-react';
import { Card, Button, Input, Select } from '../styles/GlobalStyles';
import { Expense } from '../types';

const FormContainer = styled(Card)`
  margin-bottom: 2rem;
`;

const FormGrid = styled.div`
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 1rem;
  margin-bottom: 1rem;
`;

const ButtonGroup = styled.div`
  display: flex;
  gap: 1rem;
  justify-content: flex-end;
  
  @media (max-width: 768px) {
    flex-direction: column;
  }
`;

const FormTitle = styled.h2`
  margin-bottom: 1.5rem;
  color: #333;
  font-size: 1.5rem;
`;

interface ExpenseFormProps {
  onAddExpense: (expense: Omit<Expense, 'id' | 'userId' | 'createdAt'>) => void;
  onCancel: () => void;
}

export const ExpenseForm: React.FC<ExpenseFormProps> = ({ onAddExpense, onCancel }) => {
  const [formData, setFormData] = useState({
    name: '',
    date: '',
    value: '',
    status: '' as 'Pago' | 'Pendente' | ''
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    
    if (!formData.name || !formData.date || !formData.value || !formData.status) {
      alert('Por favor, preencha todos os campos');
      return;
    }

    onAddExpense({
      name: formData.name,
      date: formData.date,
      value: parseFloat(formData.value),
      status: formData.status as 'Pago' | 'Pendente'
    });

    setFormData({ name: '', date: '', value: '', status: '' });
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    setFormData(prev => ({
      ...prev,
      [e.target.name]: e.target.value
    }));
  };

  return (
    <FormContainer>
      <FormTitle>Nova Despesa</FormTitle>
      <form onSubmit={handleSubmit}>
        <FormGrid>
          <Input
            type="text"
            name="name"
            placeholder="Nome da despesa"
            value={formData.name}
            onChange={handleChange}
            required
          />
          <Input
            type="date"
            name="date"
            value={formData.date}
            onChange={handleChange}
            required
          />
          <Input
            type="number"
            name="value"
            placeholder="Valor (R$)"
            step="0.01"
            min="0"
            value={formData.value}
            onChange={handleChange}
            required
          />
          <Select
            name="status"
            value={formData.status}
            onChange={handleChange}
            required
          >
            <option value="">Selecione o status</option>
            <option value="Pago">Pago</option>
            <option value="Pendente">Pendente</option>
          </Select>
        </FormGrid>
        
        <ButtonGroup>
          <Button type="button" variant="secondary" onClick={onCancel}>
            <X size={16} />
            Cancelar
          </Button>
          <Button type="submit">
            <Plus size={16} />
            Adicionar Despesa
          </Button>
        </ButtonGroup>
      </form>
    </FormContainer>
  );
};