import React from 'react';
import styled from 'styled-components';
import { LogOut, User } from 'lucide-react';
import { Button } from '../styles/GlobalStyles';

const HeaderContainer = styled.header`
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 1rem 0;
  margin-bottom: 2rem;
`;

const Logo = styled.div`
  display: flex;
  align-items: center;
  gap: 12px;
  
  img {
    width: 50px;
    height: 50px;
    border-radius: 12px;
  }
  
  h1 {
    color: white;
    font-size: 1.5rem;
    font-weight: 700;
  }
`;

const UserInfo = styled.div`
  display: flex;
  align-items: center;
  gap: 16px;
  color: white;
  
  .user-avatar {
    width: 40px;
    height: 40px;
    border-radius: 50%;
    border: 2px solid white;
  }
  
  .user-name {
    font-weight: 500;
  }
  
  @media (max-width: 768px) {
    .user-name {
      display: none;
    }
  }
`;

interface HeaderProps {
  user: any;
  onLogout: () => void;
}

export const Header: React.FC<HeaderProps> = ({ user, onLogout }) => {
  return (
    <HeaderContainer>
      <Logo>
        <img src="/LOGO_TOPO.jpg" alt="Logo" />
        <h1>Economia Doméstica</h1>
      </Logo>
      
      <UserInfo>
        {user?.photoURL ? (
          <img src={user.photoURL} alt="Avatar" className="user-avatar" />
        ) : (
          <User size={40} />
        )}
        <span className="user-name">{user?.displayName}</span>
        <Button variant="secondary" onClick={onLogout}>
          <LogOut size={16} />
          Sair
        </Button>
      </UserInfo>
    </HeaderContainer>
  );
};